# connect consecutive marker-9 cells along rows/cols if coordinate distance <=7
C=A.copy(); m2=np.zeros(A.shape,bool)
for r in range(A.shape[0]):
 cs=np.where(A[r]==9)[0]
 for x,y in zip(cs,cs[1:]):
  if y-x<=7: m2[r,x+1:y]=1
for c in range(A.shape[1]):
 rs=np.where(A[:,c]==9)[0]
 for x,y in zip(rs,rs[1:]):
  if y-x<=7: m2[x+1:y,c]=1
C[m2]=2
print('\n'.join(' '.join(map(str,row)) for row in C)); print('n',m2.sum())

